  void _setByPath(Map<String, dynamic> map, String path, dynamic value) {
    final parts = path.split('.');
    var current = map;
    for (var i = 0; i < parts.length - 1; i++) {
      final part = parts[i];
      current[part] ??= <String, dynamic>{};
